INSERT INTO public.cms_game_questions (id, game_type, question, options, correct_answer, explanation, difficulty, points, image, publication_status, display_order)
VALUES ('maze_maze_q1', 'maze_chase', 'Apakah struktur yang terdapat pada sel tumbuhan tetapi tiada pada sel haiwan?', '["Membran sel","Sitoplasma","Dinding sel","Nukleus"]'::jsonb, 'undefined', 'Dinding sel merupakan lapisan tegar terbina daripada selulosa yang hanya wujud pada sel tumbuhan. Sel haiwan tidak mempunyai dinding sel, sebaliknya hanya diselaputi membran sel yang fleksibel.', 'low', 50, '', 'published', maze_q1)
