INSERT INTO public.cms_game_questions (id, game_type, question, options, correct_answer, explanation, difficulty, points, image, publication_status, display_order)
VALUES ('maze_maze_q2', 'maze_chase', 'Organel manakah yang berfungsi mengawal keseluruhan aktiviti sel serta membawa maklumat genetik (DNA)?', '["Nukleus","Vakuol","Kloroplas","Dinding sel"]'::jsonb, 'undefined', 'Nukleus ialah pusat kawalan sel yang mengandungi kromosom dan bahan genetik (DNA). Ia mengawal semua tindak balas biokimia, sintesis protein dan pembahagian sel.', 'low', 50, '', 'published', maze_q2)
