INSERT INTO public.cms_game_questions (id, game_type, question, options, correct_answer, explanation, difficulty, points, image, publication_status, display_order)
VALUES ('maze_maze_q3', 'maze_chase', 'Organel manakah yang digelar sebagai "stesen janakuasa sel" kerana menghasilkan tenaga ATP melalui respirasi sel?', '["Kloroplas","Mitokondria","Jasad Golgi","Sentriol"]'::jsonb, 'undefined', 'Mitokondria mengoksidakan glukosa melalui respirasi aerob untuk membebaskan tenaga dalam bentuk molekul ATP yang sangat penting bagi kemandirian sel.', 'low', 50, '', 'published', maze_q3)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cms_game_questions (id, game_type, question, options, correct_answer, explanation, difficulty, points, image, publication_status, display_order)
VALUES ('maze_maze_q4', 'maze_chase', 'Apakah pigmen hijau di dalam kloroplas yang berfungsi menyerap tenaga cahaya matahari bagi fotosintesis?', '["Klorofil","Karotenoid","Hemoglobin","Melanin"]'::jsonb, 'undefined', 'Klorofil ialah pigmen fotosintetik hijau yang memerangkap foton cahaya suria untuk menukarkan karbon dioksida dan air kepada glukosa serta oksigen.', 'low', 50, '', 'published', maze_q4)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cms_game_questions (id, game_type, question, options, correct_answer, explanation, difficulty, points, image, publication_status, display_order)
VALUES ('maze_maze_q5', 'maze_chase', 'Apakah perbezaan saiz dan ciri vakuol antara sel tumbuhan dengan sel haiwan?', '["Tumbuhan mempunyai vakuol sentral yang besar; haiwan mempunyai vakuol kecil jika ada","Tumbuhan tiada vakuol langsung; haiwan ada vakuol besar","Kedua-dua sel tumbuhan dan haiwan berkongsi vakuol yang sama besar","Hanya sel haiwan yang mempunyai vakuol berisi sap sel"]'::jsonb, 'undefined', 'Sel tumbuhan matang memiliki vakuol tengah kekal yang besar berisi sap sel untuk mengekalkan kesegahan (turgiditi), manakala sel haiwan hanya mempunyai vakuol kecil bersaiz mikroskopik yang bersifat sementara.', 'medium', 100, '', 'published', maze_q5)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cms_game_questions (id, game_type, question, options, correct_answer, explanation, difficulty, points, image, publication_status, display_order)
VALUES ('maze_maze_q6', 'maze_chase', 'Apakah fungsi utama membran sel (plasma) yang mengelilingi sitoplasma?', '["Menghasilkan pigmen klorofil","Mengawal pergerakan bahan keluar dan masuk sel secara telap memilih","Membekalkan tenaga mekanikal tetap","Menyimpan maklumat kromosom"]'::jsonb, 'undefined', 'Membran sel merupakan lapisan dwilapisan fosfolipid separa telap yang bertindak sebagai pos kawalan sempadan sel, membenarkan molekul tertentu merentasinya.', 'medium', 100, '', 'published', maze_q6)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cms_game_questions (id, game_type, question, options, correct_answer, explanation, difficulty, points, image, publication_status, display_order)
VALUES ('maze_maze_q7', 'maze_chase', 'Apakah komposisi dan peranan cecair jeli sitoplasma di dalam sel?', '["Hanya terdiri daripada udara kering untuk pernafasan","Bahan seperti jeli yang menjadi medium bagi tindak balas biokimia sel","Lapisan keras luar sel","Gentian gentian selulosa tegar"]'::jsonb, 'undefined', 'Sitoplasma mengandungi air, ion, enzim terlarut dan organel, menyediakan persekitaran akueus optimum untuk ribuan tindak balas metabolik sel.', 'medium', 100, '', 'published', maze_q7)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cms_game_questions (id, game_type, question, options, correct_answer, explanation, difficulty, points, image, publication_status, display_order)
VALUES ('maze_maze_q8', 'maze_chase', 'Mengapakah sel tumbuhan tidak pecah (lisis) apabila diletakkan di dalam air suling berkepekatan rendah, berbanding sel darah merah haiwan?', '["Kerana sel tumbuhan mempunyai klorofil tebal","Kerana dinding selulosa yang kuat menahan tekanan osmosis turgor","Kerana sel tumbuhan tidak menyerap molekul air","Kerana vakuol tumbuhan mengecut serta-merta"]'::jsonb, 'undefined', 'Dinding selulosa tegar menghasilkan tekanan dinding bertentangan yang menahan kemasukan air osmosis berlebihan, mencegah sel tumbuhan daripada meletus (lisis).', 'high', 150, '', 'published', maze_q8)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cms_game_questions (id, game_type, question, options, correct_answer, explanation, difficulty, points, image, publication_status, display_order)
VALUES ('maze_maze_q9', 'maze_chase', 'Susun urutan organisasi sel manusia daripada peringkat paling asas kepada kompleks dengan betul:', '["Sel → Tisu → Organ → Sistem → Organisma","Tisu → Sel → Organ → Sistem → Organisma","Organ → Tisu → Sel → Sistem → Organisma","Sistem → Organ → Tisu → Sel → Organisma"]'::jsonb, 'undefined', 'Sel-sel khusus membentuk tisu, pelbagai tisu membentuk organ berfungsi, pelbagai organ membentuk sistem organ, dan rangkaian sistem menyokong organisma lengkap.', 'high', 150, '', 'published', maze_q9)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cms_game_questions (id, game_type, question, options, correct_answer, explanation, difficulty, points, image, publication_status, display_order)
VALUES ('maze_maze_q10', 'maze_chase', 'Sel darah merah matang pada mamalia tidak mempunyai nukleus. Apakah kelebihan penyesuaian biologi ini?', '["Menyediakan lebih banyak ruang bagi hemoglobin untuk mengangkut gas oksigen secara maksimum","Membolehkan sel membelah dengan lebih laju di dalam paru-paru","Mengurangkan berat sel supaya tidak mendap di saluran kapilari darah","Menghasilkan lebih banyak molekul glukosa dan ATP"]'::jsonb, 'undefined', 'Ketiadaan nukleus menghasilkan bentuk dwicekung yang meningkatkan nisbah luas permukaan kepada isi padu dan memuatkan lebih 250 juta molekul hemoglobin per sel.', 'high', 150, '', 'published', maze_q10)
