-- 7. Seed Manual Steps (7 steps)
INSERT INTO public.cms_manual_steps (id, icon, color, title, lead, body, visual_html, display_order, publication_status)
VALUES ('step_1', '🧫', 'mint', 'A. Pengenalan ARSelNel', 'Platform pembelajaran sains biologi sel interaktif Tingkatan 1.', '<p><strong>ARSelNel (Augmented Reality & Science Learning)</strong> ialah kit pembelajaran digital interaktif yang direka khas untuk membantu murid Tingkatan 1 menguasai <em>Bab 2: Sel Sebagai Unit Asas Hidupan</em> dalam Kurikulum Standard Sekolah Menengah (KSSM).</p><p>Kit ini menggabungkan penerokaan visual 3D, Realiti Terimbuh (AR), nota padat, video animasi, pembantu kecerdasan buatan (SelBot AI), serta pelbagai permainan sains interaktif.</p><ul class="manual-instruction-list"><li><span>🧭</span><span><strong>Navigasi Bar Sisi:</strong> Gunakan menu di sebelah kiri untuk berpindah dengan pantas antara 6 modul utama: <strong>Dashboard</strong>, <strong>CellQuest</strong>, <strong>Nota</strong>, <strong>Video</strong>, <strong>Tanya AI</strong>, dan <strong>Kuiz & Permainan</strong>.</span></li><li><span>📱</span><span><strong>Reka Bentuk Responsif:</strong> Berfungsi dengan lancar pada komputer meja, komputer riba, mahupun telefon pintar.</span></li></ul>', '', 0, 'published')
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cms_manual_steps (id, icon, color, title, lead, body, visual_html, display_order, publication_status)
VALUES ('step_2', '🔬', 'blue', 'B. CellQuest 3D & AR', 'Terokai struktur sel haiwan dan tumbuhan dalam 3D dan Realiti Terimbuh.', '<p>Modul <strong>CellQuest</strong> membolehkan anda membedah dan meneliti organel biologi sel secara terperinci:</p><ul class="manual-instruction-list"><li><span>🐾</span><span><strong>Tukar Jenis Sel:</strong> Klik tab <strong>🐾 Sel Haiwan</strong> atau <strong>🌿 Sel Tumbuhan</strong> untuk menukar model 3D Blender GLB.</span></li><li><span>🖱️</span><span><strong>Kawalan Kamera 360°:</strong> Seret tetikus/jari untuk memutar model; gunakan roda tetikus atau cubit skrin untuk zum masuk/keluar; klik kanan atau gunakan butang <strong>Anjak</strong> untuk mengalihkan kedudukan kamera.</span></li><li><span>👆</span><span><strong>Pilih Organel:</strong> Klik mana-mana organel pada model 3D atau klik namanya dalam senarai sisi untuk membaca fungsi biologi dan fakta sains KSSM.</span></li><li><span>◐</span><span><strong>Keratan & Label:</strong> Gunakan butang <strong>◐ Keratan: aktif</strong> untuk melihat keratan rentas organel dalaman, dan <strong>🏷️ Sembunyikan label</strong> untuk mematikan paparan teks. Tekan <strong>⟳ Tetapkan semula</strong> untuk kembali ke paparan asal.</span></li><li><span>📱</span><span><strong>Aktifkan AR:</strong> Tekan <strong>Mulakan Pengembaraan AR</strong> dan berikan kebenaran kamera pelayar apabila diminta. Halakan kamera ke permukaan rata untuk meletakkan model 3D. <em>(Keserasian AR bergantung pada sokongan WebXR peranti anda; mod 3D tetap berfungsi penuh tanpa kamera).</em></span></li></ul>', '', 0, 'published')
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cms_manual_steps (id, icon, color, title, lead, body, visual_html, display_order, publication_status)
VALUES ('step_3', '📖', 'orange', 'C. Nota Interaktif', 'Ringkasan padat fakta biologi sel berpandukan silibus KSSM.', '<p>Modul <strong>Nota Pembelajaran</strong> menyediakan rujukan visual lengkap untuk membantu pemahaman konsep sains:</p><ul class="manual-instruction-list"><li><span>📚</span><span><strong>Buka Modul Nota:</strong> Klik menu <strong>Nota</strong> pada bar sisi atau klik <strong>Mula Belajar Sekarang</strong> pada kad Cadangan Hari Ini di Dashboard.</span></li><li><span>🔬</span><span><strong>Struktur Sel Haiwan & Tumbuhan:</strong> Pelajari setiap organel seperti membran sel, sitoplasma, nukleus, mitokondrion, vakuol, kloroplas, dan dinding sel.</span></li><li><span>⚖️</span><span><strong>Jadual Perbandingan Interaktif:</strong> Bandingkan persamaan dan perbezaan antara sel haiwan dan sel tumbuhan dengan jelas dan mudah difahami.</span></li><li><span>💡</span><span><strong>Fakta Tambahan & Ulangkaji:</strong> Manfaatkan tip sains penting bagi memperkukuh pemahaman sebelum menduduki kuiz atau ujian pentaksiran sekolah.</span></li></ul>', '', 0, 'published')
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cms_manual_steps (id, icon, color, title, lead, body, visual_html, display_order, publication_status)
VALUES ('step_4', '🎬', 'violet', 'D. Video Pembelajaran', 'Perkukuh kefahaman sains dengan animasi 3D dan simulasi eksperimen.', '<p>Modul <strong>Perpustakaan Video</strong> menawarkan media video interaktif bagi membantu visualisasi proses biologi mikroskopik:</p><ul class="manual-instruction-list"><li><span>▶️</span><span><strong>Tonton Video Animasi:</strong> Saksikan simulasi pergerakan bahan melalui membran sel, proses fotosintesis di dalam kloroplas, dan respirasi sel di mitokondrion.</span></li><li><span>🔬</span><span><strong>Demonstrasi Makmal:</strong> Tonton cara penyediaan slaid sel pipi (sel haiwan) dan slaid sel epidermis bawang (sel tumbuhan) di bawah mikroskop cahaya.</span></li><li><span>⏯️</span><span><strong>Kawalan Penuh:</strong> Anda boleh menjeda (*pause*), mengulang (*replay*), dan menonton dalam mod skrin penuh untuk mencatat maklumat sains penting.</span></li></ul>', '', 0, 'published')
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cms_manual_steps (id, icon, color, title, lead, body, visual_html, display_order, publication_status)
VALUES ('step_5', '🤖', 'pink', 'E. Tanya AI — SelBot', 'Pembantu tutor maya anda untuk menjawab soalan sains sepanjang masa.', '<p><strong>SelBot AI</strong> ialah pembantu pintar peribadi anda untuk menyelesaikan sebarang kemusykilan biologi sel:</p><ul class="manual-instruction-list"><li><span>💬</span><span><strong>Cara Bertanya:</strong> Buka modul <strong>Tanya AI</strong>, taipkan soalan sains anda ke dalam kotak sembang, dan tekan butang hantar atau Enter.</span></li><li><span>💡</span><span><strong>Contoh Soalan Yang Boleh Ditanya:</strong></span></li></ul><div class="manual-note" style="margin-top:4px;">• <em>"Apakah fungsi nukleus?"</em><br>• <em>"Apakah perbezaan sel haiwan dan sel tumbuhan?"</em><br>• <em>"Mengapa sel tumbuhan mempunyai kloroplas?"</em><br>• <em>"Apakah peranan mitokondrion sebagai penjana tenaga?"</em></div><p style="margin-top:10px;">Anda boleh terus bertanya soalan susulan untuk mendapatkan penerangan sains yang lebih mendalam.</p>', '', 0, 'published')
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cms_manual_steps (id, icon, color, title, lead, body, visual_html, display_order, publication_status)
VALUES ('step_6', '🎮', 'green', 'F. Kuiz & Permainan Sains', 'Uji pengetahuan anda melalui 5 cabaran permainan interaktif yang menyeronokkan!', '<p>Akses <strong>Kuiz & Permainan Sains</strong> melalui bar sisi atau butang <strong>Mulakan Cabaran Sains</strong> di Dashboard. Terdapat 5 permainan interaktif utama:</p><ul class="manual-instruction-list"><li><span>🏷️</span><span><strong>Labelkan Organel:</strong> Tarik dan lepaskan label nama organel pada gambar rajah sel haiwan dan sel tumbuhan dengan tepat.</span></li><li><span>🕹️</span><span><strong>Maze Chase: Misi Sel Haiwan & Tumbuhan:</strong> Permainan arked 2D! Baca soalan sains, cari zon jawapan yang betul di dalam maze, kutip <em>power-up</em>, dan elak virus yang mengejar anda.</span></li><li><span>🌳</span><span><strong>Susun Organisasi Kehidupan:</strong> Susun hierarki organisasi kehidupan mengikut urutan yang betul: <em>Sel → Tisu → Organ → Sistem → Organisma</em>.</span></li><li><span>⚡</span><span><strong>Kuiz Saintis Muda:</strong> Jawab soalan kuiz aneka pilihan rawak secara pantas untuk mengumpul mata ganjaran.</span></li><li><span>🔬</span><span><strong>Misi Makmal Sains:</strong> Pengembaraan makmal 2D interaktif meneroka 10 radas makmal dan menyelesaikan soalan eksperimen sains.</span></li></ul>', '', 0, 'published')
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.cms_manual_steps (id, icon, color, title, lead, body, visual_html, display_order, publication_status)
VALUES ('step_7', '🛠️', 'teal', 'G. Bantuan & Penyelesaian Masalah', 'Panduan pantas sekiranya anda menghadapi sebarang kekangan teknikal.', '<p>Berikut merupakan langkah penyelesaian mudah untuk isu-isu teknikal lazim:</p><ul class="manual-instruction-list"><li><span>🌐</span><span><strong>Model 3D gagal dimuatkan:</strong> Pastikan anda membuka ARSelNel melalui pelayan web tempatan (contoh: <code>http://localhost:3000</code>) dan bukannya membuka fail secara terus (<code>file://</code>).</span></li><li><span>📷</span><span><strong>Kamera AR tidak berfungsi:</strong> Semak sama ada pelayar dan peranti anda menyokong WebXR serta berikan kebenaran kamera (*Allow Camera*). Jika peranti tidak menyokong AR, gunakan mod 3D interaktif yang berfungsi sepenuhnya.</span></li><li><span>🎬</span><span><strong>Video tidak dimainkan:</strong> Semak kelajuan capaian internet anda dan pastikan tetapan pelayar tidak menyekat media.</span></li><li><span>🤖</span><span><strong>SelBot tidak memberi respons:</strong> Pastikan soalan berkaitan topik sains ditaip dengan ringkas dan jelas, kemudian tekan butang hantar sekali lagi.</span></li><li><span>🎮</span><span><strong>Permainan tidak dapat dikawal:</strong> Gunakan kekunci anak panah atau WASD pada papan kekunci komputer, atau gunakan butang kawalan skrin pada peranti sentuh.</span></li><li><span>🏠</span><span><strong>Cara kembali ke Dashboard:</strong> Anda boleh menekan pautan <strong>← Kembali ke Dashboard</strong> di bahagian atas atau memilih menu <strong>Dashboard</strong> pada bar sisi bila-bila masa.</span></li></ul>', '', 0, 'published')
ON CONFLICT (id) DO NOTHING;

